/* Taxonomy combo widget for Decap CMS: free-text input with suggestions.
 * Suggestions come from taxonomies.json (generated by gen-taxonomies.py);
 * anything typed is accepted as-is, so existing and brand-new terms share
 * a single field. Slugs derive at build time.
 *
 * Field config: { widget: "taxlabel", options_source: "categories" | "tags" }
 */
(function () {
  var CACHE = null;

  function loadOptions() {
    if (CACHE) return Promise.resolve(CACHE);
    return fetch("taxonomies.json", { credentials: "same-origin" })
      .then(function (res) {
        if (!res.ok) throw new Error("taxonomies.json missing");
        return res.json();
      })
      .then(function (data) {
        CACHE = data;
        return data;
      })
      .catch(function () {
        return { categories: [], tags: [] };
      });
  }

  var TaxLabel = createClass({
    getInitialState: function () {
      return { options: [] };
    },
    componentDidMount: function () {
      var source = this.props.field.get("options_source");
      var self = this;
      loadOptions().then(function (data) {
        self.setState({ options: data[source] || [] });
      });
    },
    render: function () {
      var value = this.props.value || "";
      var onChange = this.props.onChange;
      var name = this.props.field.get("name");
      var listId = "taxlabel-" + name + "-" + Math.random().toString(36).slice(2);
      return h(
        "div",
        null,
        h("input", {
          type: "text",
          value: value,
          list: listId,
          placeholder: "type or pick…",
          style: { width: "100%" },
          onChange: function (e) {
            onChange(e.target.value);
          },
        }),
        h(
          "datalist",
          { id: listId },
          this.state.options.map(function (o) {
            return h("option", { value: o });
          }),
        ),
      );
    },
  });

  function register() {
    if (window.CMS && window.CMS.registerWidget) {
      window.CMS.registerWidget("taxlabel", TaxLabel);
    } else {
      setTimeout(register, 100);
    }
  }
  register();
})();
